// Parse a WhatsApp Business Cloud API delivery-status webhook event.
//
// This node NEVER returns recipient phone numbers, message content, or the
// raw webhook payload. It stores nothing and sends nothing -- it only
// extracts a small, safe status summary. Only the FIRST status event in the
// payload is processed if more than one is present (see documentation).
//
// Every provider-controlled value is bounded and format-checked before use:
// an opaque identifier being "just a string" does not make it safe to pass
// through unchecked -- oversized or control-character-laden values are
// rejected/normalized rather than trusted.

const item = $input.first().json;
const payload = item.body !== undefined ? item.body : item;

function safeGet(obj, path, fallback) {
  try {
    let cur = obj;
    for (const key of path) {
      if (cur === null || cur === undefined) return fallback;
      cur = cur[key];
    }
    return cur === undefined ? fallback : cur;
  } catch (e) {
    return fallback;
  }
}

// Opaque Meta message IDs look like "wamid.<base64-ish>" -- bound the length
// and restrict to the characters realistically used (letters, digits, and
// the handful of punctuation characters base64/URL-safe encodings use).
function isValidProviderMessageId(v) {
  return typeof v === 'string' && /^[A-Za-z0-9._=+\/-]{1,256}$/.test(v);
}

const KNOWN_STATUSES = ['sent', 'delivered', 'read', 'failed'];
function isKnownStatus(v) {
  return KNOWN_STATUSES.includes(v);
}
// A future, currently-unknown status value is only ever passed through if it
// looks like a safe status token: lowercase letters/underscores, bounded
// length. Anything else (control characters, oversized, mixed case, etc.)
// becomes the literal string "unknown" instead.
function isSafeUnknownStatusToken(v) {
  return typeof v === 'string' && /^[a-z_]{1,32}$/.test(v);
}

// Only a bounded, digits-only Unix timestamp representation is accepted.
function isValidTimestamp(v) {
  if (typeof v !== 'string' && typeof v !== 'number') return false;
  return /^\d{1,20}$/.test(String(v));
}

// A provider error code must be a safe 32-bit integer, or a short
// alphanumeric/underscore/hyphen token -- never arbitrary text, whitespace,
// or control characters, which could carry diagnostic detail we must never
// return.
const INT32_BOUND = 2 ** 31;
function isValidErrorCode(v) {
  if (typeof v === 'number') return Number.isInteger(v) && Math.abs(v) < INT32_BOUND;
  if (typeof v === 'string') return /^[A-Za-z0-9_-]{1,64}$/.test(v);
  return false;
}

const IGNORED = { providerMessageId: null, deliveryStatus: null, eventTimestamp: null, errorCode: null, processingStatus: 'ignored' };

let result;

try {
  if (!payload || typeof payload !== 'object') {
    result = IGNORED;
  } else {
    const entry = safeGet(payload, ['entry', 0], null);
    const change = entry ? safeGet(entry, ['changes', 0], null) : null;
    const value = change ? safeGet(change, ['value'], null) : null;

    if (!value) {
      result = IGNORED;
    } else {
      const statuses = Array.isArray(value.statuses) ? value.statuses : [];

      if (statuses.length === 0) {
        result = IGNORED;
      } else {
        // Process only the first status event; any additional entries in
        // this payload are intentionally not processed (see documentation).
        const first = statuses[0];
        const rawId = first.id;

        if (!isValidProviderMessageId(rawId)) {
          // An invalid or oversized ID means we cannot trust this event
          // enough to report anything about it at all.
          result = IGNORED;
        } else {
          const providerMessageId = rawId;
          const rawStatus = first.status;

          let deliveryStatus;
          if (isKnownStatus(rawStatus) || isSafeUnknownStatusToken(rawStatus)) {
            deliveryStatus = rawStatus;
          } else {
            deliveryStatus = 'unknown';
          }

          const eventTimestamp = isValidTimestamp(first.timestamp) ? String(first.timestamp) : null;

          let errorCode = null;
          if (deliveryStatus === 'failed') {
            const code = safeGet(first, ['errors', 0, 'code'], null);
            errorCode = isValidErrorCode(code) ? code : null;
          }

          result = { providerMessageId, deliveryStatus, eventTimestamp, errorCode, processingStatus: 'parsed' };
        }
      }
    }
  }
} catch (err) {
  result = IGNORED;
}

return [{ json: result }];
